css:
.lonelychair-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e8ecf3;
    background: linear-gradient(165deg, #161b27 0%, #1d2433 55%, #232c40 100%);
    border-radius: 18px;
}

.lonelychair-container * {
    box-sizing: border-box;
}

.lonelychair-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0f1420 0%, #2a2238 55%, #3a2a1c 100%);
    color: #f4f1ea;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #34405a;
    box-shadow: 0 12px 34px rgba(0, 0, 0, 0.45);
}

.lonelychair-header h1 {
    margin: 8px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #f6efe1;
}

.lonelychair-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e8b873;
    background: rgba(232, 184, 115, 0.12);
    border: 1px solid rgba(232, 184, 115, 0.28);
    padding: 5px 14px;
    border-radius: 999px;
}

.lonelychair-subtitle {
    margin: 12px auto 0;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.6;
    color: #c8cedd;
}

.lonelychair-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #aeb7c9;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.lonelychair-period-counter #currentDay,
.lonelychair-period-counter #maxPeriods {
    font-weight: 800;
    color: #f6efe1;
}

.lonelychair-round-name {
    background: rgba(232, 184, 115, 0.15);
    color: #f0c98a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid rgba(232, 184, 115, 0.3);
}

.lonelychair-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ff9d8a;
    background: rgba(192, 57, 43, 0.18);
    padding: 4px 12px;
    border-radius: 999px;
    border: 1px solid rgba(255, 124, 104, 0.3);
}

.lonelychair-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.lonelychair-status-card {
    background: #222b3d;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #313c54;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.28);
    border-top: 4px solid #5a6b8c;
}

.lonelychair-card-engagement { border-top-color: #3a9d8f; }
.lonelychair-card-wellbeing { border-top-color: #8a6fce; }
.lonelychair-card-quality { border-top-color: #4f8fd6; }
.lonelychair-card-delivery { border-top-color: #e8a13c; }

.lonelychair-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8d97ad;
}

.lonelychair-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #f1f4f9;
}

.lonelychair-card-engagement .lonelychair-value { color: #4fc4b3; }
.lonelychair-card-wellbeing .lonelychair-value { color: #a98fe6; }
.lonelychair-card-quality .lonelychair-value { color: #6fa9e8; }
.lonelychair-card-delivery .lonelychair-value { color: #f0b454; }

.lonelychair-sublabel {
    font-size: 0.76rem;
    color: #8d97ad;
    line-height: 1.35;
}

.lonelychair-kpi-good .lonelychair-value { color: #4fc4b3; }
.lonelychair-kpi-warn .lonelychair-value { color: #f0b454; }
.lonelychair-kpi-bad .lonelychair-value { color: #ff7c68; }

.lonelychair-resource-bars {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
    margin-bottom: 18px;
}

.lonelychair-resource-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 18px;
    border-radius: 12px;
    font-weight: 700;
    font-size: 0.9rem;
}

.lonelychair-hours-bar {
    background: #2a2238;
    color: #ddd2f0;
    border: 1px solid #3f3357;
}

.lonelychair-budget-bar {
    background: #2c2a1c;
    color: #f0e4c8;
    border: 1px solid #4a4128;
}

.lonelychair-resource-bar #hoursDisplay,
.lonelychair-resource-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.lonelychair-hours-over {
    color: #ff7c68 !important;
}

.lonelychair-briefing {
    display: flex;
    gap: 14px;
    background: #222b3d;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    border: 1px solid #313c54;
    border-left: 5px solid #e8a13c;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.25);
}

.lonelychair-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.lonelychair-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #f0c98a;
    margin-bottom: 6px;
}

.lonelychair-briefing-text {
    font-size: 0.95rem;
    line-height: 1.6;
    color: #c8cedd;
}

.lonelychair-briefing-text strong { color: #4fc4b3; }
.lonelychair-briefing-text em { color: #ff9d8a; font-style: italic; }

.lonelychair-controls {
    background: #1f2735;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #313c54;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.25);
}

.lonelychair-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #f6efe1;
    border-bottom: 2px solid #313c54;
    padding-bottom: 8px;
}

.lonelychair-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #d3dae8;
    margin: 14px 0 6px;
}

.lonelychair-container select,
.lonelychair-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #3c4860;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #161b27;
    color: #e8ecf3;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.lonelychair-container select:focus,
.lonelychair-container input[type="number"]:focus {
    outline: none;
    border-color: #e8a13c;
    box-shadow: 0 0 0 3px rgba(232, 161, 60, 0.18);
}

.lonelychair-container select option {
    background-color: #161b27;
    color: #e8ecf3;
}

.lonelychair-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #e8a13c;
}

.lonelychair-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #aeb7c9;
    margin-top: 4px;
}

.lonelychair-range-readout span:last-child {
    color: #f0b454;
    font-weight: 800;
}

.lonelychair-hint {
    font-size: 0.8rem;
    color: #8d97ad;
    margin-top: 4px;
    line-height: 1.4;
}

.lonelychair-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.lonelychair-container .btn-primary {
    background: linear-gradient(135deg, #c97f22 0%, #e8a13c 100%);
    border: none;
    color: #1a1206;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(201, 127, 34, 0.35);
}

.lonelychair-container .btn-primary:hover {
    filter: brightness(1.07);
}

.lonelychair-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #3c4860;
    color: #aeb7c9;
    background: transparent;
}

.lonelychair-container .btn-outline-secondary:hover {
    background: #2a3346;
    color: #e8ecf3;
}

.lonelychair-coach {
    background: linear-gradient(135deg, #1a1426 0%, #251c34 100%);
    color: #e8ddf4;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid #3f3357;
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.35);
}

.lonelychair-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #c2a0f0;
    margin-bottom: 8px;
}

.lonelychair-coach-body {
    font-size: 0.95rem;
    line-height: 1.6;
}

.lonelychair-coach-body strong { color: #f0c98a; }
.lonelychair-coach-body em { color: #ff9d8a; font-style: italic; }

.lonelychair-history,
.lonelychair-chart {
    background: #1f2735;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #313c54;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.25);
}

.lonelychair-history h3,
.lonelychair-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #f6efe1;
}

.lonelychair-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #c8cedd;
}

.lonelychair-container table#usfHistoryTable th {
    background: #2a3346;
    color: #f0c98a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #3c4860;
}

.lonelychair-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #2a3346;
}

.lonelychair-container table#usfHistoryTable tr:nth-child(even) td {
    background: #232c40;
}

.lonelychair-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .lonelychair-container {
        padding: 14px;
    }
    .lonelychair-header h1 {
        font-size: 1.8rem;
    }
    .lonelychair-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .lonelychair-value {
        font-size: 2rem;
    }
    .lonelychair-clock {
        margin-left: 0;
    }
    .lonelychair-period-counter {
        font-size: 0.88rem;
    }
    .lonelychair-resource-bars {
        grid-template-columns: 1fr;
    }
    .lonelychair-resource-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .lonelychair-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen ---- */
.lonelychair-completion { padding: 8px 4px 4px; }
.lonelychair-cm-head { text-align: center; margin-bottom: 16px; }
.lonelychair-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #e8a13c; }
.lonelychair-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #f0c98a; }
.lonelychair-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #e8ecf3; }
.lonelychair-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.lonelychair-cm-yes { background: rgba(79,196,179,0.16); color: #4fc4b3; border: 1px solid rgba(79,196,179,0.45); }
.lonelychair-cm-no { background: rgba(233,109,109,0.14); color: #ef9a9a; border: 1px solid rgba(233,109,109,0.5); }
.lonelychair-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.lonelychair-cm-metric { flex: 1 1 120px; min-width: 108px; background: rgba(111,169,232,0.08); border: 1px solid rgba(111,169,232,0.22); border-radius: 10px; padding: 10px 8px; text-align: center; }
.lonelychair-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #6fa9e8; }
.lonelychair-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #aeb7c9; text-transform: uppercase; letter-spacing: 0.03em; }
.lonelychair-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #e8ecf3; }
.lonelychair-cm-insights { margin: 0; padding-left: 20px; }
.lonelychair-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #c8cedd; }

