(function() {
    'use strict';

    class LonelyChairAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Lonely Chair`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Talea Digital Solutions / Project Atlas).
            this.START_ENGAGEMENT = 61;   // pulse fell 74 -> 61 since the leadership change
            this.START_WELLBEING = 42;    // leader-wellbeing index /100
            this.START_QUALITY = 38;      // decision quality; 23 queued, cycle time tripled 2->6 days
            this.START_DELIVERY = 30;     // Atlas confidence; 5 weeks behind an 8-week runway
            this.TARGET = 60;             // credible recovery target per KPI
            this.HOURS_CAP = 20;          // Elena's scarce discretionary hours each round
            this.BUDGET_CAP = 120;        // EUR 120k support budget, in thousands

            // Concept truths: isolation/non-delegation is the binding constraint.
            this.TRUE_ROOT = `isolation`;
            this.TRUE_PRIORITY = `support`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    engagement: this.START_ENGAGEMENT,
                    wellbeing: this.START_WELLBEING,
                    quality: this.START_QUALITY,
                    delivery: this.START_DELIVERY,
                    hoursUsed: 0,
                    budgetUsed: 0,
                    hasSupport: false,
                    hasProtocol: false,
                    rivalRepaired: false,
                    rivalLost: false,
                    greenTheatre: false,
                    targetMissed: false,
                    engagementHistory: [this.START_ENGAGEMENT],
                    wellbeingHistory: [this.START_WELLBEING],
                    qualityHistory: [this.START_QUALITY],
                    deliveryHistory: [this.START_DELIVERY],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    root: `isolation`,
                    priority: `support`,
                    candor: 60,
                    support: `coachstaff`,
                    delegate: `rival`,
                    protocol: `thresholds`,
                    recovery: 6,
                    atlas: `scope`,
                    rival: `engage`,
                    boardPosture: `amber`,
                    weekend: 60,
                    model: `institutionalise`,
                    rivalResolve: `reposition`,
                    boardUpdate: `honest`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const root = document.getElementById(`rootInput`);
                const prio = document.getElementById(`priorityInput`);
                const cand = document.getElementById(`candorInput`);
                if (root) decisions.root = root.value;
                if (prio) decisions.priority = prio.value;
                if (cand) decisions.candor = parseInt(cand.value, 10);
                if (!Number.isFinite(decisions.candor) || decisions.candor < 0 || decisions.candor > 100) {
                    warn(`warn_candor_range`); return false;
                }
            } else if (round === 2) {
                const sup = document.getElementById(`supportInput`);
                const del = document.getElementById(`delegateInput`);
                const pro = document.getElementById(`protocolInput`);
                const rec = document.getElementById(`recoveryInput`);
                if (sup) decisions.support = sup.value;
                if (del) decisions.delegate = del.value;
                if (pro) decisions.protocol = pro.value;
                if (rec) decisions.recovery = parseFloat(rec.value);
                if (!Number.isFinite(decisions.recovery) || decisions.recovery < 0 || decisions.recovery > 14) {
                    warn(`warn_recovery_range`); return false;
                }
            } else if (round === 3) {
                const atl = document.getElementById(`atlasInput`);
                const riv = document.getElementById(`rivalInput`);
                const bp = document.getElementById(`boardPostureInput`);
                const wk = document.getElementById(`weekendInput`);
                if (atl) decisions.atlas = atl.value;
                if (riv) decisions.rival = riv.value;
                if (bp) decisions.boardPosture = bp.value;
                if (wk) decisions.weekend = parseInt(wk.value, 10);
                if (!Number.isFinite(decisions.weekend) || decisions.weekend < 0 || decisions.weekend > 100) {
                    warn(`warn_weekend_range`); return false;
                }
            } else if (round === 4) {
                const mo = document.getElementById(`modelInput`);
                const rr = document.getElementById(`rivalResolveInput`);
                const bu = document.getElementById(`boardUpdateInput`);
                const cv = document.getElementById(`convictionInput`);
                if (mo) decisions.model = mo.value;
                if (rr) decisions.rivalResolve = rr.value;
                if (bu) decisions.boardUpdate = bu.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Per-KPI deltas this round; spend/hours are resource usage.
            let engD = 0, wellD = 0, qualD = 0, delD = 0;
            let spend = 0, hours = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the isolation, not effort/team/schedule (Common Error 1: the hero trap).
                if (d.root === this.TRUE_ROOT) {
                    qualD += 12; wellD += 6; coachKey = `coach_r1_root_right`;
                } else if (d.root === `effort`) {
                    wellD -= 10; qualD -= 4; coachKey = `coach_r1_effort`;
                } else if (d.root === `team`) {
                    engD -= 8; qualD -= 4; coachKey = `coach_r1_team`;
                } else {
                    qualD -= 6; coachKey = `coach_r1_schedule`;
                }

                // First relationship to rebuild: a confidential support relationship.
                if (d.priority === this.TRUE_PRIORITY) {
                    wellD += 10; qualD += 6;
                    if (d.root === this.TRUE_ROOT) coachKey = `coach_r1_diag_sharp`;
                } else if (d.priority === `board`) {
                    qualD += 2; coachKey = `coach_r1_boardonly`;
                } else if (d.priority === `client`) {
                    engD -= 4; coachKey = `coach_r1_clientonly`;
                } else {
                    wellD -= 8; qualD -= 6; coachKey = `coach_r1_none`;
                }

                // Candor: naming isolation honestly vs pretending more effort will do it.
                if (d.candor >= 60) { qualD += 6; wellD += 4; }
                else if (d.candor <= 25) { qualD -= 6; coachKey = `coach_r1_lowcandor`; }

                summaryKey = (d.root === this.TRUE_ROOT && d.priority === this.TRUE_PRIORITY) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Build the support architecture (Common Errors 1, 2 & 6 + the abdication trap).
                switch (d.support) {
                    case `coachstaff`: spend += 70; hours += 6; wellD += 16; qualD += 12; ds.hasSupport = true; coachKey = `coach_r2_coachstaff`; break;
                    case `peerboard`: spend += 20; hours += 4; wellD += 12; qualD += 8; ds.hasSupport = true; coachKey = `coach_r2_peerboard`; break;
                    case `staffonly`: spend += 45; hours += 4; qualD += 8; wellD += 2; coachKey = `coach_r2_staffonly`; break;
                    case `none`: wellD -= 10; qualD -= 6; coachKey = `coach_r2_nosupport`; break;
                }

                // Delegation: trusting the rival with a real mandate repairs the relationship and
                // clears the queue; routing around him plants the knowledge-loss risk; holding
                // everything is the hero trap; delegating to all at once invites errors.
                switch (d.delegate) {
                    case `rival`: qualD += 10; engD += 8; ds.rivalRepaired = true; coachKey = `coach_r2_rival`; break;
                    case `lieutenants`: qualD += 6; engD += 2; coachKey = `coach_r2_lieutenants`; break;
                    case `all`: qualD -= 8; coachKey = `coach_r2_delegateall`; break;
                    case `hold`: qualD -= 12; wellD -= 8; coachKey = `coach_r2_hold`; break;
                }

                // Delegation protocol: escalation thresholds are what make delegation safe
                // (Common Error 2: abdication via delegation).
                switch (d.protocol) {
                    case `thresholds`: qualD += 10; delD += 4; ds.hasProtocol = true; break;
                    case `checkin`: qualD += 2; break;
                    case `none`: qualD -= 8; delD -= 6; coachKey = `coach_r2_noprotocol`; break;
                }
                // Delegating real authority WITHOUT a protocol is abdication: a costly error slips.
                if (d.protocol === `none` && (d.delegate === `all` || d.delegate === `rival` || d.delegate === `lieutenants`)) {
                    qualD -= 6; delD -= 4; coachKey = `coach_r2_abdication`;
                }

                // Protected recovery: an input to decision quality, not an indulgence.
                if (d.recovery >= 5) { wellD += 8; qualD += 3; }
                else if (d.recovery <= 1) { wellD -= 6; coachKey = `coach_r2_norecovery`; }

                summaryKey = (ds.hasSupport && ds.hasProtocol && d.delegate !== `hold`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Six live decisions under pressure; the support structure should change HOW she decides.
                const supportBonus = ds.hasSupport ? 1 : 0;

                // Atlas recovery within the penalty/renewal stakes.
                switch (d.atlas) {
                    case `scope`: delD += 14; qualD += 6; coachKey = `coach_r3_scope`; break;
                    case `contractors`: delD += 6; engD -= 4; coachKey = `coach_r3_contractors`; break;
                    case `date`: delD -= 10; qualD -= 6; coachKey = `coach_r3_date`; break;
                }

                // The rival (Common Error 5: avoiding the rival = a delivery risk, not a soft extra).
                switch (d.rival) {
                    case `engage`: engD += 8; delD += 8; qualD += 4; ds.rivalRepaired = true; coachKey = `coach_r3_engage`; break;
                    case `ignore`: engD -= 8; delD -= 12; ds.rivalLost = true; coachKey = `coach_r3_ignore`; break;
                    case `push`: engD -= 6; delD -= 6; coachKey = `coach_r3_push`; break;
                }

                // Board communication posture (Common Error 4: green theatre).
                switch (d.boardPosture) {
                    case `amber`: qualD += 8; wellD += 4; coachKey = (d.atlas === `scope`) ? `coach_r3_amber` : coachKey; break;
                    case `green`: delD -= 6; qualD -= 8; ds.greenTheatre = true; coachKey = `coach_r3_green`; break;
                    case `silent`: qualD -= 4; coachKey = `coach_r3_silent`; break;
                }

                // Holding the line on wellbeing under pressure (Common Error 3: burning the team).
                if (d.weekend >= 60) {
                    engD += 8; wellD += 8;
                    // But protecting recovery only helps delivery if scope was made realistic.
                    if (d.atlas !== `date`) delD += 4;
                } else if (d.weekend <= 25) {
                    // Spending the people for the date: a short delivery blip then attrition that re-risks it.
                    engD -= 14; wellD -= 10; delD -= 6; coachKey = `coach_r3_burnout`;
                }

                // Support structure pays off: it materially lifts decision quality when it exists.
                qualD += supportBonus * 5;

                summaryKey = (d.atlas === `scope` && d.rival === `engage` && d.boardPosture === `amber` && d.weekend >= 50) ? `sum_r3_good` :
                    (d.boardPosture === `green` || d.weekend <= 25 ? `sum_r3_bad` : `sum_r3_weak`);
            } else if (round === 4) {
                // Sustain performance: institutionalise the model and present to the board.
                switch (d.model) {
                    case `institutionalise`: wellD += 12; qualD += 10; engD += 6; coachKey = `coach_r4_institutionalise`; break;
                    case `partial`: wellD -= 4; qualD += 2; coachKey = `coach_r4_partial`; break;
                    case `revert`: wellD -= 14; qualD -= 10; coachKey = `coach_r4_revert`; break;
                }

                // Resolve the rival for the long term.
                switch (d.rivalResolve) {
                    case `reposition`: engD += 10; delD += 6; ds.rivalRepaired = true; coachKey = (d.model === `institutionalise`) ? `coach_r4_reposition` : coachKey; break;
                    case `release`: engD += 2; delD -= 2; coachKey = `coach_r4_release`; break;
                    case `sideline`: engD -= 10; delD -= 8; ds.rivalLost = true; coachKey = `coach_r4_sideline`; break;
                }

                // The board update.
                switch (d.boardUpdate) {
                    case `honest`: qualD += 8; engD += 4; coachKey = (d.model === `institutionalise` && d.rivalResolve === `reposition`) ? `coach_r4_honest` : coachKey; break;
                    case `hero`: wellD -= 8; engD -= 6; qualD -= 6; coachKey = `coach_r4_hero`; break;
                    case `vague`: qualD -= 4; coachKey = `coach_r4_vague`; break;
                }

                // Conviction nudges decision quality.
                qualD += Math.round((d.conviction - 60) / 8);
            }

            // Resource accounting.
            ds.budgetUsed = Math.min(this.BUDGET_CAP, Math.round(ds.budgetUsed + spend));
            ds.hoursUsed = Math.round(ds.hoursUsed + hours);

            // Apply KPI deltas, clamped to 0–100.
            ds.engagement = Math.max(0, Math.min(100, ds.engagement + engD));
            ds.wellbeing = Math.max(0, Math.min(100, ds.wellbeing + wellD));
            ds.quality = Math.max(0, Math.min(100, ds.quality + qualD));
            ds.delivery = Math.max(0, Math.min(100, ds.delivery + delD));

            ds.engagementHistory.push(Math.round(ds.engagement));
            ds.wellbeingHistory.push(Math.round(ds.wellbeing));
            ds.qualityHistory.push(Math.round(ds.quality));
            ds.deliveryHistory.push(Math.round(ds.delivery));

            if (round === this.ROUNDS.length) {
                const allHit = ds.engagement >= this.TARGET && ds.wellbeing >= this.TARGET && ds.quality >= this.TARGET && ds.delivery >= this.TARGET;
                ds.targetMissed = !allHit;
            }

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                engagement: Math.round(ds.engagement),
                engagementDelta: Math.round(engD),
                wellbeing: Math.round(ds.wellbeing),
                wellbeingDelta: Math.round(wellD),
                quality: Math.round(ds.quality),
                qualityDelta: Math.round(qualD),
                delivery: Math.round(ds.delivery),
                deliveryDelta: Math.round(delD),
                hoursUsed: ds.hoursUsed,
                budgetUsed: ds.budgetUsed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

