        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Equal-weight formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const engagement = Math.round(ds.engagement);
            const wellbeing = Math.round(ds.wellbeing);
            const quality = Math.round(ds.quality);
            const delivery = Math.round(ds.delivery);
            const composite = Math.round(engagement * 0.25 + wellbeing * 0.25 + quality * 0.25 + delivery * 0.25);
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.totalScore === `number`) ? s.totalScore
                : (typeof s.overallScore === `number` ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || ``;
            const met = !!s.allHit;
            const badge = met
                ? `<span class="lonelychair-cm-badge lonelychair-cm-yes">` + T(`cm_won`) + `</span>`
                : `<span class="lonelychair-cm-badge lonelychair-cm-no">` + T(`cm_notwon`) + `</span>`;
            const riskBadge = s.deliveredButBroke
                ? ` <span class="lonelychair-cm-badge lonelychair-cm-no">` + T(`cm_pyrrhic`) + `</span>`
                : ``;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="lonelychair-cm-metric"><span class="lonelychair-cm-mv">` + Math.round(s.engagement || 0) + `</span><span class="lonelychair-cm-ml">` + T(`cm_m_engagement`) + `</span></div>`
                + `<div class="lonelychair-cm-metric"><span class="lonelychair-cm-mv">` + Math.round(s.wellbeing || 0) + `</span><span class="lonelychair-cm-ml">` + T(`cm_m_wellbeing`) + `</span></div>`
                + `<div class="lonelychair-cm-metric"><span class="lonelychair-cm-mv">` + Math.round(s.quality || 0) + `</span><span class="lonelychair-cm-ml">` + T(`cm_m_quality`) + `</span></div>`
                + `<div class="lonelychair-cm-metric"><span class="lonelychair-cm-mv">` + Math.round(s.delivery || 0) + `</span><span class="lonelychair-cm-ml">` + T(`cm_m_delivery`) + `</span></div>`;
            return ``
                + `<div class="lonelychair-completion">`
                +   `<div class="lonelychair-cm-head">`
                +     `<div class="lonelychair-cm-score">` + score + `<span class="lonelychair-cm-score-max">/100</span></div>`
                +     `<div class="lonelychair-cm-grade">` + grade + ` ` + badge + riskBadge + `</div>`
                +   `</div>`
                +   `<div class="lonelychair-cm-metrics">` + metrics + `</div>`
                +   `<div class="lonelychair-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="lonelychair-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const engagement = Math.round(ds.engagement);
            const wellbeing = Math.round(ds.wellbeing);
            const quality = Math.round(ds.quality);
            const delivery = Math.round(ds.delivery);

            const allHit = engagement >= this.TARGET && wellbeing >= this.TARGET && quality >= this.TARGET && delivery >= this.TARGET;
            const deliveredButBroke = delivery >= this.TARGET && (wellbeing < 40 || engagement < 50);
            const composite = Math.round(engagement * 0.25 + wellbeing * 0.25 + quality * 0.25 + delivery * 0.25);

            let performance = window.mySimulation.t(`perf_isolated`);
            if (allHit && composite >= 72) performance = window.mySimulation.t(`perf_sustainable`);
            else if (allHit) performance = window.mySimulation.t(`perf_credible`);
            else if (deliveredButBroke) performance = window.mySimulation.t(`perf_pyrrhic`);
            else if (delivery >= this.TARGET) performance = window.mySimulation.t(`perf_delivered_thin`);
            else if (composite >= this.START_DELIVERY + 18) performance = window.mySimulation.t(`perf_improving`);

            const insights = [];
            if (allHit && wellbeing >= this.TARGET) insights.push(window.mySimulation.t(`insight_sustainable`));
            else if (deliveredButBroke) insights.push(window.mySimulation.t(`insight_pyrrhic`));
            else if (delivery >= this.TARGET) insights.push(window.mySimulation.t(`insight_thin`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (wellbeing < 40) insights.push(window.mySimulation.t(`insight_lowwellbeing`));
            if (!ds.hasSupport) insights.push(window.mySimulation.t(`insight_nosupport`));
            if (ds.rivalLost) insights.push(window.mySimulation.t(`insight_rivallost`));
            else if (ds.rivalRepaired) insights.push(window.mySimulation.t(`insight_rivalkept`));
            if (ds.greenTheatre) insights.push(window.mySimulation.t(`insight_greentheatre`));
            if (allHit && ds.hasProtocol && ds.hasSupport) insights.push(window.mySimulation.t(`insight_architecture`));

            return {
                engagement: engagement,
                wellbeing: wellbeing,
                quality: quality,
                delivery: delivery,
                allHit: allHit,
                deliveredButBroke: deliveredButBroke,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.greenTheatre) return window.mySimulation.t(`hint_green`);
            if (ds.wellbeing < 30 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_wellbeing`);
            if (!ds.hasSupport && state.currentPeriod >= 2) return window.mySimulation.t(`hint_support`);
            if (ds.rivalLost) return window.mySimulation.t(`hint_rival`);
            if (state.currentPeriod >= 3 && ds.delivery < 45) return window.mySimulation.t(`hint_delivery`);
            if (ds.engagement >= this.TARGET && ds.wellbeing >= this.TARGET && ds.quality >= this.TARGET && ds.delivery >= this.TARGET) return window.mySimulation.t(`hint_strong`);
            return null;
        }

